"use strict";(self.webpackChunkmeridiant_docs=self.webpackChunkmeridiant_docs||[]).push([["266"],{6164(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docs":[{"type":"category","label":"Introduction","collapsed":false,"items":[{"type":"link","href":"/docs/intro","label":"What is Meridiant","docId":"intro","unlisted":false},{"type":"link","href":"/docs/why-canton","label":"Why Canton","docId":"why-canton","unlisted":false}],"collapsible":true},{"type":"category","label":"How it works","collapsed":false,"items":[{"type":"link","href":"/docs/how-it-works","label":"Overview","docId":"how-it-works","unlisted":false},{"type":"link","href":"/docs/markets","label":"Isolated markets","docId":"markets","unlisted":false},{"type":"link","href":"/docs/supplying","label":"Supplying","docId":"supplying","unlisted":false},{"type":"link","href":"/docs/borrowing","label":"Borrowing","docId":"borrowing","unlisted":false},{"type":"link","href":"/docs/liquidation","label":"Liquidation","docId":"liquidation","unlisted":false},{"type":"link","href":"/docs/prices-and-rates","label":"Prices and rates","docId":"prices-and-rates","unlisted":false}],"collapsible":true},{"type":"category","label":"Who\'s involved","collapsed":false,"items":[{"type":"link","href":"/docs/who-is-involved","label":"Participants","docId":"who-is-involved","unlisted":false},{"type":"link","href":"/docs/privacy-and-trust","label":"Privacy and trust","docId":"privacy-and-trust","unlisted":false}],"collapsible":true},{"type":"category","label":"The product","collapsed":false,"items":[{"type":"link","href":"/docs/what-we-are-building","label":"What we are building","docId":"what-we-are-building","unlisted":false},{"type":"link","href":"/docs/getting-started","label":"Getting started","docId":"getting-started","unlisted":false},{"type":"link","href":"/docs/glossary","label":"Glossary","docId":"glossary","unlisted":false}],"collapsible":true}]},"docs":{"borrowing":{"id":"borrowing","title":"Borrowing","description":"Lock collateral you still own, draw a smaller loan against a fresh price, and repay at any time. You cannot walk away with the collateral while the debt is live.","sidebar":"docs"},"getting-started":{"id":"getting-started","title":"Getting started","description":"Meridiant is invite-gated. This page is how to think about joining as a supplier, borrower, or partner \u2014 not a public signup flow.","sidebar":"docs"},"glossary":{"id":"glossary","title":"Glossary","description":"Plain-language terms used across the Meridiant docs.","sidebar":"docs"},"how-it-works":{"id":"how-it-works","title":"How it works","description":"Meridiant is over-collateralized, isolated-market lending \u2014 suppliers provide an asset, borrowers lock collateral they still own, and unsafe loans can be closed by anyone.","sidebar":"docs"},"intro":{"id":"intro","title":"What is Meridiant","description":"Meridiant is isolated-market lending on Canton Network \u2014 private positions, atomic settlement, and risk that stays inside each market.","sidebar":"docs"},"liquidation":{"id":"liquidation","title":"Liquidation","description":"When a loan is unsafe, anyone can repay it and receive discounted collateral. The whole close happens in one transaction. Surplus stays with the borrower.","sidebar":"docs"},"markets":{"id":"markets","title":"Isolated markets","description":"Each Meridiant market is its own book \u2014 one collateral, one loan asset, one oracle, one risk profile. Trouble does not cascade.","sidebar":"docs"},"prices-and-rates":{"id":"prices-and-rates","title":"Prices and rates","description":"Borrowing and liquidation use a fresh, signed price. Interest follows how much of the pool is borrowed, with a steeper curve once utilization passes a target.","sidebar":"docs"},"privacy-and-trust":{"id":"privacy-and-trust","title":"Privacy and trust","description":"Positions are private by default. The operator is bounded. Collateral stays borrower-owned. Mainnet is intended to be self-custodial at the key layer.","sidebar":"docs"},"supplying":{"id":"supplying","title":"Supplying","description":"Deposit a market\'s loan asset, earn interest as borrowers pay it, and withdraw unused liquidity. Each market is its own pool.","sidebar":"docs"},"what-we-are-building":{"id":"what-we-are-building","title":"What we are building","description":"A Canton-native isolated lending venue \u2014 working protocol now, invite-gated networks next, self-custodial mainnet after that.","sidebar":"docs"},"who-is-involved":{"id":"who-is-involved","title":"Who\'s involved","description":"Suppliers, borrowers, and liquidators use the markets. An operator, an oracle, and Canton asset issuers make the venue run. Meridiant is a product of Catalyst Labs.","sidebar":"docs"},"why-canton":{"id":"why-canton","title":"Why Canton","description":"Canton gives Meridiant privacy, atomic settlement, and institutional counterparties as protocol features \u2014 not as a marketing layer on top of a public chain.","sidebar":"docs"}}}}')}}]);